import { AlertCircle, ArrowLeft, BarChart3, CalendarDays, Check, Download, ExternalLink, FileCheck2, FileText, Layers, Link2, Paperclip, Pencil, Plus, RefreshCw, Search, SlidersHorizontal, Trash2, Upload, X } from 'lucide-react';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { Link, Navigate, NavLink, useNavigate, useParams } from 'react-router-dom';
import { Bar, BarChart, CartesianGrid, Legend, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { Badge, EmptyState, Modal, PageTitle } from '../components/ui';
import { useAuth } from '../features/auth';
import { useData } from '../features/data';
import { useLinkedGraduates } from '../features/graduates';
import { downloadCsv, effectiveSubmission, failureRate, findCourseByCode, formatDate, gradeMetrics, gradeTemplateRows, importantDatesForTerm, normalizeStageLinkUrl, parseGradeFile, parseTargetCsv, stageVisualStatus, trackerSummary } from '../lib/domain';
import type { AcademicTermDraft, Course, CourseEditDraft, GradeCsvResult, ImportantDate, Profile, Stage, StageStatus } from '../lib/types';

export function TrackerPage(){
  const{trackerId:id,tab='timeline'}=useParams();const navigate=useNavigate();const data=useData();const{profile}=useAuth();const tracker=data.trackers.find(t=>t.id===id);const termStorageKey=`fbit:selected-term:${id??'tracker'}`;const[term,setTermState]=useState(()=>localStorage.getItem(termStorageKey)??data.currentTerm);const[selectedCourse,setSelectedCourse]=useState<string|undefined>(data.courses[0]?.id);const[stageModal,setStageModal]=useState<Stage|null|undefined>();const[gradeModal,setGradeModal]=useState(false);const[termModal,setTermModal]=useState(false);const[editCourseModal,setEditCourseModal]=useState<Course>();const[deleteCourseModal,setDeleteCourseModal]=useState<Course>();const[overrideCourse,setOverrideCourse]=useState<string>();const[toast,setToast]=useState('');
  const setTerm=useCallback((value:string)=>{setTermState(value);localStorage.setItem(termStorageKey,value)},[termStorageKey]);
  useEffect(()=>{if(data.terms.length&&!data.terms.includes(term))setTerm(data.currentTerm||data.terms[0])},[data.currentTerm,data.terms,term,setTerm]);
  if(!tracker)return <Navigate to="/dashboard" replace/>;
  if(tracker.type==='general'&&tab!=='timeline')return <Navigate to={`/trackers/${tracker.id}/timeline`} replace/>;
  const summary=trackerSummary(tracker);const course=data.courses.find(c=>c.id===selectedCourse)??data.courses[0];const canManageTerms=['dean','academic_director'].includes(profile?.role??'');const canManageCourses=['dean','academic_director','chair','program_lead'].includes(profile?.role??'');const notify=(message:string)=>{setToast(message);window.setTimeout(()=>setToast(''),3200)};
  return <div className="mx-auto max-w-7xl p-5 md:p-8"><Link to="/dashboard" className="mb-3 inline-flex items-center gap-1 text-xs font-bold text-[#003C71] hover:text-[#EA7600]"><ArrowLeft size={15}/>Back to dashboard</Link><PageTitle title={tracker.title} body={tracker.description} actions={<div className="flex items-center gap-2"><Badge tone="blue">{tracker.category}</Badge><button className="btn-ghost text-red-600" onClick={async()=>{if(confirm(`Delete ${tracker.title}?`)){await data.deleteTracker(tracker.id);navigate('/dashboard')}}}><Trash2 size={16}/></button></div>}/>
    <LinkedGraduateNavigation trackerId={tracker.id}/>
    <div className="card mb-6 flex items-center gap-6 p-4"><div><p className="text-[9px] font-black uppercase tracking-wider text-slate-500">Mandatory completion</p><p className="text-2xl font-black text-[#003C71]">{summary.progress}%</p></div><div className="h-3 flex-1 overflow-hidden rounded-full bg-slate-200"><div className="h-full rounded-full bg-[#EA7600] transition-all" style={{width:`${summary.progress}%`}}/></div><Badge tone={summary.status==='Completed'?'green':summary.status==='Attention Required'?'red':'yellow'}>{summary.status}</Badge></div>
    {tracker.type==='grade-submission'&&<div className="mb-6 flex overflow-x-auto border-b border-slate-200">{[['timeline','Timeline & stages',CalendarDays],['analytics','Grade analytics',BarChart3],['submissions','Submission checklist',FileCheck2]].map(([key,label,Icon]:any)=><NavLink key={key} to={`/trackers/${tracker.id}/${key}`} className={({isActive})=>`flex shrink-0 items-center gap-2 border-b-2 px-4 py-3 text-[11px] font-extrabold uppercase tracking-wider ${isActive?'border-[#EA7600] text-[#EA7600]':'border-transparent text-slate-500 hover:text-slate-900'}`}><Icon size={16}/>{label}</NavLink>)}</div>}
    {tab==='timeline'&&<Timeline tracker={tracker} editStage={setStageModal} uploadDocument={async(stageId,file)=>{await data.uploadDocument(tracker.id,stageId,file);notify('Document attached.')}} addStageLink={async(stageId,title,url)=>{await data.addStageLink(tracker.id,stageId,title,url);notify('Link attached.')}} deleteStageLink={async linkId=>{await data.deleteStageLink(linkId);notify('Link removed.')}}/>}
    {tab==='analytics'&&<>
      <div className="card mb-4 flex flex-wrap items-center gap-2 p-4" aria-label="Grade analytics actions">
        <button className="btn-primary gap-2" onClick={()=>downloadCsv(`Final_Grades_Template_${term}.csv`,gradeTemplateRows(term))}><Download size={14}/>Download CSV template</button>
        {canManageTerms&&<button className="btn-ghost gap-2" onClick={()=>setTermModal(true)}><Plus size={14}/>Create term</button>}
      </div>
      {course?<GradeAnalytics courses={data.courses} course={course} term={term} setTerm={setTerm} setCourse={setSelectedCourse} settings={{average:tracker.averageThreshold??data.settings.averageThreshold,pass:tracker.passRateThreshold??data.settings.passRateThreshold}} openUpload={()=>setGradeModal(true)} canManageCourses={canManageCourses} onEditCourse={setEditCourseModal} onDeleteCourse={setDeleteCourseModal}/>:<div className="card"><EmptyState title="No courses yet" body="Upload grades or import a target list to add the first course."/></div>}
    </>}
    {tab==='submissions'&&<Submissions courses={data.courses} term={term} setTerm={setTerm} overrides={data.overrides} onUpload={(courseId)=>{setSelectedCourse(courseId);setGradeModal(true)}} onOverride={setOverrideCourse} importTargets={async(file)=>{const result=await parseTargetCsv(file);if(result.errors.length)throw new Error(result.errors.join(' '));await data.importTargets(tracker.id,result.rows,file);notify(`Imported ${result.rows.length} target courses.`)}}/>}
    {stageModal!==undefined&&<StageEditor stage={stageModal} count={tracker.stages.length} term={term} importantDates={data.importantDates} onClose={()=>setStageModal(undefined)} onSave={async(stage)=>{await data.saveStage(tracker.id,stage);setStageModal(undefined);notify('Milestone saved.')}} onDelete={stageModal?async()=>{await data.deleteStage(tracker.id,stageModal.id);setStageModal(undefined);notify('Milestone deleted.')} : undefined}/>}
    {tab==='timeline'&&<button className="btn-primary fixed bottom-6 right-6 gap-2 shadow-xl" onClick={()=>setStageModal(null)}><Plus size={16}/>Add stage</button>}
    {gradeModal&&<GradeUpload courses={data.courses} terms={data.terms} canCreateTerms={canManageTerms} onCreateTerm={data.createAcademicTerm} onClose={()=>setGradeModal(false)} onSubmit={async(courseCode,courseTitle,fileTerm,grades)=>{const outcome=await data.submitGrades(courseCode,courseTitle,fileTerm,grades);setSelectedCourse(outcome.courseId);setTerm(fileTerm);setGradeModal(false);notify(outcome.duplicate?`Duplicate ignored: ${outcome.courseCode} already has these grades for ${fileTerm}.`:outcome.createdCourse?`Added ${outcome.courseCode} and submitted ${grades.length} de-identified grades for ${fileTerm}.`:`Submitted ${grades.length} de-identified grades to ${outcome.courseCode} for ${fileTerm}.`)}}/>}
    {termModal&&<AcademicTermEditor onClose={()=>setTermModal(false)} onSave={async(value)=>{const code=await data.createAcademicTerm(value);setTerm(code);setTermModal(false);notify(`Academic term ${code} created and selected.`)}}/>}
    {editCourseModal&&<CourseEditorModal course={editCourseModal} term={term} profiles={data.profiles} onClose={()=>setEditCourseModal(undefined)} onSave={async value=>{await data.updateCourse(editCourseModal.id,term,value);setEditCourseModal(undefined);notify(`Updated ${value.code.trim().toUpperCase()} for ${term}.`)}}/>}
    {deleteCourseModal&&<DeleteCourseModal course={deleteCourseModal} term={term} hasTerm={Boolean(deleteCourseModal.termDetails?.[term]||deleteCourseModal.terms[term])} onClose={()=>setDeleteCourseModal(undefined)} onDelete={async scope=>{const removed=deleteCourseModal;const fallback=data.courses.find(item=>item.id!==removed.id)?.id;await data.removeCourse(removed.id,term,scope);if(scope==='history')setSelectedCourse(fallback);setDeleteCourseModal(undefined);notify(scope==='history'?`Deleted ${removed.code} and its entire history.`:`Removed ${removed.code} from ${term}.`)}}/>}
    {overrideCourse&&<OverrideModal course={data.courses.find(c=>c.id===overrideCourse)!} current={data.overrides[`${overrideCourse}_${term}`]} onClose={()=>setOverrideCourse(undefined)} onSave={async(value,reason)=>{await data.setOverride(overrideCourse,term,value,reason);setOverrideCourse(undefined);notify(value?'Manual override saved.':'Returned to automatic status.')}}/>}
    {toast&&<div role="status" className="fixed bottom-6 right-6 z-50 flex items-center gap-2 rounded-lg bg-slate-950 px-4 py-3 text-xs font-bold text-white shadow-xl"><Check size={15} className="text-emerald-400"/>{toast}</div>}
  </div>;
}

function LinkedGraduateNavigation({ trackerId }: { trackerId: string }) {
  const linked = useLinkedGraduates(trackerId);
  if (linked.error) return <p role="alert" className="mb-4 text-xs text-red-700">Linked student navigation could not be loaded. <button className="underline" onClick={() => void linked.refetch()}>Retry</button></p>;
  if (!linked.data?.length) return null;
  return <nav aria-label="Linked MSc students" className="card mb-4 flex flex-wrap gap-3 p-3">{linked.data.map(student => <Link key={student.id} to={`/graduates?student=${student.id}`} className="inline-flex items-center gap-1 text-xs font-bold text-[#003C71] hover:underline"><ArrowLeft size={14}/>MSc progress: {student.student_name}</Link>)}</nav>;
}

function Timeline({tracker,editStage,uploadDocument,addStageLink,deleteStageLink}:{tracker:any;editStage(s:Stage):void;uploadDocument(id:string,file:File):Promise<void>;addStageLink(id:string,title:string,url:string):Promise<void>;deleteStageLink(id:string):Promise<void>}){
  const stages=[...tracker.stages].sort((a:Stage,b:Stage)=>a.sortOrder-b.sortOrder);
  const[attachmentStage,setAttachmentStage]=useState<Stage>();
  return <div className="space-y-6">
    <div className="card overflow-x-auto p-6"><div className="relative flex min-w-[720px] items-start py-4"><div className="absolute left-10 right-10 top-[42px] h-1 bg-slate-200"/>{stages.map((stage:Stage)=>{const visual=stageVisualStatus(stage);const tone=visual==='completed'?'bg-emerald-600 border-emerald-700':visual==='overdue'?'bg-red-600 border-red-700':visual==='in-progress'?'bg-[#003C71] border-blue-950':'bg-white border-slate-300 text-slate-400';return <button key={stage.id} onClick={()=>editStage(stage)} className="relative z-10 flex flex-1 flex-col items-center px-2 text-center"><span className="mb-2 text-[10px] font-bold text-slate-500">{formatDate(stage.dueDate)}</span><span className={`grid h-9 w-9 place-items-center rounded-full border-2 text-white shadow-sm ${tone}`}>{visual==='completed'?<Check size={16}/>:visual==='overdue'?<AlertCircle size={16}/>:<span className="h-2.5 w-2.5 rounded-full bg-current"/>}</span><span className={`mt-3 max-w-36 text-xs font-extrabold ${visual==='overdue'?'text-red-700':'text-slate-800'}`}>{stage.title}</span><span className="mt-1"><Badge tone={visual==='completed'?'green':visual==='overdue'?'red':visual==='in-progress'?'blue':'yellow'}>{visual}</Badge></span></button>})}</div></div>
    <div className="card overflow-hidden">
      <div className="border-b border-slate-200 bg-slate-50 px-5 py-3 text-[10px] font-black uppercase tracking-wider text-slate-500">Detailed milestone checklist</div>
      {stages.length===0?<EmptyState title="No stages yet" body="Add the first milestone to build this process."/>:<ul className="divide-y divide-slate-100">{stages.map((stage:Stage)=><li key={stage.id} className="flex flex-col gap-4 p-5 hover:bg-slate-50 lg:flex-row lg:items-center">
        <button className="flex-1 text-left" onClick={()=>editStage(stage)}><div className="flex items-center gap-2"><b className="text-sm text-slate-900">{stage.title}</b>{!stage.isRequired&&<Badge>Optional</Badge>}</div><p className="mt-1 text-xs text-slate-500">{stage.description||'No description provided.'}</p></button>
        <div className="flex items-center gap-3"><span className="text-xs font-semibold text-slate-500">{formatDate(stage.dueDate)}</span><Badge tone={stageVisualStatus(stage)==='overdue'?'red':stage.status==='completed'?'green':'yellow'}>{stageVisualStatus(stage)}</Badge><button type="button" className="btn-ghost gap-1" onClick={()=>setAttachmentStage(stage)}><Paperclip size={14}/>Attach</button></div>
        {(stage.documents.length>0||(stage.links?.length??0)>0)&&<div className="space-y-1.5 lg:w-64">
          {stage.documents.map(document=><div key={document.id} className="flex items-center gap-1.5 truncate text-[11px] font-semibold text-[#003C71]"><FileText size={13} className="shrink-0"/><span className="truncate">{document.name}</span></div>)}
          {(stage.links??[]).map(link=><div key={link.id} className="group flex items-center gap-1 rounded-md border border-blue-100 bg-blue-50/60 px-2 py-1">
            <a className="flex min-w-0 flex-1 items-center gap-1.5 text-[11px] font-bold text-[#003C71] hover:text-[#EA7600] hover:underline" href={link.url} target="_blank" rel="noopener noreferrer"><Link2 size={13} className="shrink-0"/><span className="truncate">{link.title}</span><ExternalLink size={11} className="shrink-0"/></a>
            <button type="button" className="rounded p-1 text-slate-400 hover:bg-red-50 hover:text-red-600" aria-label={`Remove link ${link.title}`} onClick={()=>{if(confirm(`Remove link “${link.title}”?`))void deleteStageLink(link.id)}}><Trash2 size={12}/></button>
          </div>)}
        </div>}
      </li>)}</ul>}
    </div>
    {attachmentStage&&<AttachmentModal stage={attachmentStage} onClose={()=>setAttachmentStage(undefined)} uploadFile={file=>uploadDocument(attachmentStage.id,file)} addLink={(title,url)=>addStageLink(attachmentStage.id,title,url)}/>}
  </div>;
}

function AttachmentModal({stage,onClose,uploadFile,addLink}:{stage:Stage;onClose():void;uploadFile(file:File):Promise<void>;addLink(title:string,url:string):Promise<void>}){
  const[mode,setMode]=useState<'file'|'url'>('file');const[file,setFile]=useState<File>();const[title,setTitle]=useState('');const[url,setUrl]=useState('');const[busy,setBusy]=useState(false);const[error,setError]=useState('');const[message,setMessage]=useState('');
  async function submit(event:React.FormEvent){event.preventDefault();setError('');setMessage('');setBusy(true);try{if(mode==='file'){if(!file)throw new Error('Choose a file to attach.');await uploadFile(file);onClose();return;}const cleanUrl=normalizeStageLinkUrl(url);const cleanTitle=title.trim()||new URL(cleanUrl).hostname.replace(/^www\./,'');await addLink(cleanTitle,cleanUrl);setTitle('');setUrl('');setMessage('Link attached. You can add another link or close this window.');}catch(reason){setError(reason instanceof Error?reason.message:'The attachment could not be added.');}finally{setBusy(false)}}
  return <Modal title={`Attach to ${stage.title}`} onClose={onClose}><form className="space-y-5 p-6" onSubmit={submit}>
    <div className="grid grid-cols-2 rounded-lg bg-slate-100 p-1"><button type="button" className={`rounded-md px-4 py-2 text-xs font-bold ${mode==='file'?'bg-white text-[#003C71] shadow-sm':'text-slate-500'}`} onClick={()=>{setMode('file');setError('');setMessage('')}}><FileText className="mr-2 inline" size={15}/>Choose file</button><button type="button" className={`rounded-md px-4 py-2 text-xs font-bold ${mode==='url'?'bg-white text-[#003C71] shadow-sm':'text-slate-500'}`} onClick={()=>{setMode('url');setError('');setMessage('')}}><Link2 className="mr-2 inline" size={15}/>Specify URL</button></div>
    {mode==='file'?<label><span className="label">Document</span><span className="field flex cursor-pointer items-center gap-3 py-3"><Upload size={17} className="text-[#003C71]"/><span className="min-w-0 flex-1 truncate text-xs">{file?.name??'Choose a PDF, DOC, or DOCX file'}</span><input className="sr-only" type="file" accept=".pdf,.doc,.docx" onChange={event=>setFile(event.target.files?.[0])}/></span></label>:<div className="space-y-4"><label><span className="label">Link name <span className="font-normal normal-case text-slate-400">(optional)</span></span><input className="field" maxLength={160} value={title} onChange={event=>setTitle(event.target.value)} placeholder="e.g. Faculty submission guide"/></label><label><span className="label">URL</span><input className="field" required type="url" value={url} onChange={event=>setUrl(event.target.value)} placeholder="https://example.com/resource"/></label></div>}
    {message&&<p className="rounded-lg bg-emerald-50 p-3 text-xs font-bold text-emerald-700" role="status">{message}</p>}{error&&<p className="rounded-lg bg-red-50 p-3 text-xs font-bold text-red-700" role="alert">{error}</p>}
    <div className="flex justify-end gap-2"><button type="button" className="btn-ghost" onClick={onClose}>Close</button><button className="btn-orange gap-2" disabled={busy}>{mode==='file'?<Upload size={15}/>:<Link2 size={15}/>} {busy?'Adding…':mode==='file'?'Attach file':'Add link'}</button></div>
  </form></Modal>;
}

function TermSelect({term,setTerm}:{term:string;setTerm(v:string):void}){const{terms}=useData();return <label className="flex items-center gap-2 text-[10px] font-black uppercase tracking-wider text-slate-500">Active term<select className="field w-auto py-2" value={term} onChange={e=>setTerm(e.target.value)}>{terms.map(t=><option key={t}>{t}</option>)}</select></label>}

type AnalyticsMode='single'|'multi'|'thresholds';

function courseInstructor(course:Course,term:string){return course.termDetails?.[term]?.instructor??course.instructor}

function GradeAnalytics({courses,course,term,setTerm,setCourse,settings,openUpload,canManageCourses,onEditCourse,onDeleteCourse}:{courses:Course[];course:Course;term:string;setTerm(v:string):void;setCourse(v:string):void;settings:{average:number;pass:number};openUpload():void;canManageCourses:boolean;onEditCourse(course:Course):void;onDeleteCourse(course:Course):void}){
  const[mode,setMode]=useState<AnalyticsMode>('single');
  const[search,setSearch]=useState('');
  const[selected,setSelected]=useState<string[]>([course.id]);
  const metrics=course.terms[term];
  const history=Object.entries(course.terms).filter(([,value])=>value).map(([historyTerm,value])=>({term:historyTerm,average:value!.average,passRate:value!.passRate,failureRate:failureRate(value!),enrolled:value!.enrolled}));
  const visibleCourses=courses.filter(item=>`${item.code} ${item.title} ${item.department} ${courseInstructor(item,term)}`.toLowerCase().includes(search.trim().toLowerCase()));
  return <div className="space-y-6">
    <div className="card flex flex-col justify-between gap-4 p-4 xl:flex-row xl:items-center">
      <div className="flex flex-wrap rounded-lg bg-slate-100 p-1" role="tablist" aria-label="Grade analytics views">
        {([['single','Single course vs history'],['multi','Multi-course compare'],['thresholds','Threshold finder']] as Array<[AnalyticsMode,string]>).map(([key,label])=><button key={key} role="tab" aria-selected={mode===key} className={`rounded-md px-4 py-2 text-xs font-bold ${mode===key?'bg-white text-[#003C71] shadow-sm':'text-slate-500'}`} onClick={()=>setMode(key)}>{key==='thresholds'&&<SlidersHorizontal className="mr-1.5 inline" size={13}/>} {label}</button>)}
      </div>
      <div className="flex flex-wrap items-center gap-2"><TermSelect term={term} setTerm={setTerm}/><button className="btn-orange gap-2" onClick={openUpload}><Upload size={14}/>Upload grades</button></div>
    </div>
    {mode==='single'&&<div className="grid gap-6 lg:grid-cols-3">
      <aside className="card p-5">
        <label className="relative block"><Search className="absolute left-3 top-3 text-slate-400" size={15}/><span className="sr-only">Search courses</span><input className="field pl-9" placeholder="Search code, title, instructor…" value={search} onChange={event=>setSearch(event.target.value)}/></label>
        <p className="mt-3 text-[10px] font-bold text-slate-500">{visibleCourses.length} of {courses.length} courses</p>
        <div className="mt-3 max-h-[560px] space-y-2 overflow-y-auto">{visibleCourses.map(item=><div key={item.id} className={`flex items-start rounded-lg border ${item.id===course.id?'border-[#003C71] bg-blue-50':'border-slate-100 hover:bg-slate-50'}`}>
          <button className="min-w-0 flex-1 p-3 text-left" onClick={()=>setCourse(item.id)}><b className="text-xs text-[#003C71]">{item.code}</b><p className="truncate text-xs font-semibold">{item.title}</p><p className="mt-1 truncate text-[10px] text-slate-500">{courseInstructor(item,term)}{item.termDetails?.[term]?.section?` · Section ${item.termDetails[term]!.section}`:''}</p></button>
          {canManageCourses&&<div className="flex shrink-0 gap-0.5 p-2"><button className="rounded p-1.5 text-slate-500 hover:bg-white hover:text-[#003C71]" aria-label={`Edit ${item.code}`} title={`Edit ${item.code}`} onClick={()=>onEditCourse(item)}><Pencil size={14}/></button><button className="rounded p-1.5 text-slate-500 hover:bg-red-50 hover:text-red-700" aria-label={`Remove ${item.code}`} title={`Remove ${item.code}`} onClick={()=>onDeleteCourse(item)}><Trash2 size={14}/></button></div>}
        </div>)}</div>
      </aside>
      <div className="space-y-6 lg:col-span-2">
        <div className="card p-6">
          <div className="flex flex-col justify-between gap-4 border-b border-slate-100 pb-4 sm:flex-row">
            <div><Badge tone="blue">{course.code}</Badge><h2 className="mt-2 text-lg font-extrabold">{course.title}</h2><p className="text-xs text-slate-500">Instructor: {courseInstructor(course,term)}{course.termDetails?.[term]?.section?` · Section ${course.termDetails[term]!.section}`:''}</p></div>
            {canManageCourses&&<div className="flex gap-1"><button className="btn-ghost gap-1" onClick={()=>onEditCourse(course)}><Pencil size={14}/>Edit</button><button className="btn-ghost px-2 text-red-700" aria-label={`Remove selected course ${course.code}`} title={`Remove ${course.code}`} onClick={()=>onDeleteCourse(course)}><Trash2 size={16}/></button></div>}
          </div>
          {metrics?<div className="my-6 grid grid-cols-3 gap-3">{[['Class average',`${metrics.average}%`],['Pass rate',`${metrics.passRate}%`],['Enrolled',metrics.enrolled]].map(([label,value])=><div key={label} className="rounded-xl border border-slate-200 bg-slate-50 p-4 text-center"><p className="text-[9px] font-black uppercase text-slate-500">{label}</p><p className="mt-1 text-2xl font-black text-[#003C71]">{value}</p></div>)}</div>:<div className="my-6 rounded-lg border border-amber-200 bg-amber-50 p-4 text-xs text-amber-800">No grade submission for {course.code} in {term}.</div>}
          <h3 className="text-[10px] font-black uppercase tracking-wider text-slate-600">Historical course trend</h3><div className="h-72"><ResponsiveContainer><LineChart data={history}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="term"/><YAxis domain={[0,100]}/><Tooltip/><Legend/><Line dataKey="average" name="Class average (%)" stroke="#003C71" strokeWidth={3}/><Line dataKey="passRate" name="Pass rate (%)" stroke="#10b981" strokeWidth={2} strokeDasharray="5 5"/><Line dataKey="failureRate" name="Failure rate (%)" stroke="#dc2626" strokeWidth={2} strokeDasharray="3 3"/></LineChart></ResponsiveContainer></div>
        </div>
        {metrics&&<div className="card p-6"><h3 className="text-[10px] font-black uppercase tracking-wider text-slate-600">Grade distribution · {term}</h3><div className="h-64"><ResponsiveContainer><BarChart data={Object.entries(metrics.distribution).map(([grade,count])=>({grade,count}))}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="grade"/><YAxis/><Tooltip/><Bar dataKey="count" fill="#EA7600" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></div>}
      </div>
    </div>}
    {mode==='multi'&&<MultiCourseComparison courses={courses} term={term} selected={selected} setSelected={setSelected} settings={settings}/>}
    {mode==='thresholds'&&<ThresholdAnalysis courses={courses} term={term}/>}
  </div>
}

function MultiCourseComparison({courses,term,selected,setSelected,settings}:{courses:Course[];term:string;selected:string[];setSelected(value:string[]):void;settings:{average:number;pass:number}}){
  const[search,setSearch]=useState('');
  const eligible=courses.filter(course=>course.terms[term]);
  const visible=eligible.filter(course=>`${course.code} ${course.title} ${courseInstructor(course,term)}`.toLowerCase().includes(search.trim().toLowerCase()));
  const comparison=eligible.filter(course=>selected.includes(course.id)).map(course=>({id:course.id,code:course.code,title:course.title,instructor:courseInstructor(course,term),...course.terms[term]!}));
  const add=(id:string)=>{if(!selected.includes(id))setSelected([...selected,id])};
  const remove=(id:string)=>setSelected(selected.filter(item=>item!==id));
  return <div className="space-y-6">
    <div className="grid gap-5 lg:grid-cols-2">
      <section className="card p-5"><div className="mb-3 flex items-center justify-between"><div><h2 className="font-extrabold">Available courses</h2><p className="text-xs text-slate-500">Search and click a course to add it.</p></div><button className="btn-ghost text-xs" onClick={()=>setSelected(eligible.map(item=>item.id))}>Select all ({eligible.length})</button></div><label className="relative block"><Search className="absolute left-3 top-3 text-slate-400" size={15}/><span className="sr-only">Search available courses</span><input className="field pl-9" placeholder="Search code, title, instructor…" value={search} onChange={event=>setSearch(event.target.value)}/></label><div className="mt-3 max-h-80 divide-y divide-slate-100 overflow-y-auto rounded-lg border border-slate-200">{visible.map(item=><button key={item.id} className="flex w-full items-center justify-between gap-3 px-3 py-2.5 text-left text-xs hover:bg-slate-50 disabled:bg-slate-50 disabled:text-slate-400" disabled={selected.includes(item.id)} onClick={()=>add(item.id)}><span className="min-w-0"><b className="text-[#003C71]">{item.code}</b><span className="ml-2 truncate text-slate-600">{item.title}</span></span><span className="shrink-0 font-bold">{selected.includes(item.id)?'Selected':'Add'}</span></button>)}</div></section>
      <section className="card p-5"><div className="mb-3 flex items-center justify-between"><div><h2 className="font-extrabold">Comparison list</h2><p className="text-xs text-slate-500">{comparison.length} selected for {term}</p></div><button className="btn-ghost text-xs" disabled={!selected.length} onClick={()=>setSelected([])}>Deselect all</button></div><div className="max-h-[372px] divide-y divide-slate-100 overflow-y-auto rounded-lg border border-slate-200">{comparison.length?comparison.map(item=><div key={item.id} className="flex items-center gap-3 px-3 py-2.5 text-xs"><span className="min-w-0 flex-1"><b className="text-[#003C71]">{item.code}</b><span className="ml-2 text-slate-600">{item.title}</span></span><button className="rounded p-1 text-slate-400 hover:bg-red-50 hover:text-red-700" aria-label={`Remove ${item.code} from comparison`} onClick={()=>remove(item.id)}><X size={14}/></button></div>):<p className="p-6 text-center text-xs text-slate-500">No courses selected.</p>}</div></section>
    </div>
    <div className="card p-6"><div className="flex items-center justify-between"><div><h2 className="font-extrabold">Class average and pass-rate comparison</h2><p className="text-xs text-slate-500">Thresholds: average {settings.average}% · pass rate {settings.pass}%</p></div><Layers className="text-[#EA7600]"/></div>{comparison.length===0?<p className="py-16 text-center text-xs text-slate-500">Add courses to build a comparison.</p>:comparison.length>30?<p className="mt-6 rounded-lg border border-blue-100 bg-blue-50 p-4 text-xs text-blue-900">The chart is hidden for selections over 30 courses to keep this view readable. All selected courses remain in the table below.</p>:<div className="mt-4 h-80"><ResponsiveContainer><BarChart data={comparison}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="code"/><YAxis domain={[0,100]}/><Tooltip/><Legend/><Bar dataKey="average" fill="#003C71"/><Bar dataKey="passRate" fill="#10b981"/></BarChart></ResponsiveContainer></div>}</div>
    <CourseComparisonTable rows={comparison} settings={settings}/>
  </div>
}

function CourseComparisonTable({rows,settings}:{rows:Array<{id:string;code:string;title:string;instructor:string;enrolled:number;average:number;passRate:number}>;settings:{average:number;pass:number}}){return <div className="card overflow-x-auto"><table className="w-full min-w-[700px]"><thead><tr className="table-head"><th className="p-4">Course</th><th>Instructor</th><th>Enrolled</th><th>Average</th><th>Pass rate</th><th className="pr-4 text-right">Flag</th></tr></thead><tbody className="divide-y divide-slate-100 text-xs">{rows.map(row=>{const flag=row.average<settings.average||row.passRate<settings.pass;return <tr key={row.id}><td className="p-4"><b>{row.code}</b><p className="text-slate-500">{row.title}</p></td><td>{row.instructor}</td><td>{row.enrolled}</td><td className="font-bold">{row.average}%</td><td className="font-bold">{row.passRate}%</td><td className="pr-4 text-right"><Badge tone={flag?'red':'green'}>{flag?'Requires attention':'Normal range'}</Badge></td></tr>})}</tbody></table>{rows.length===0&&<p className="p-8 text-center text-xs text-slate-500">No courses to display.</p>}</div>}

function ThresholdAnalysis({courses,term}:{courses:Course[];term:string}){
  const[metric,setMetric]=useState<'average'|'failureRate'>('average');
  const[operator,setOperator]=useState<'below'|'above'>('below');
  const[value,setValue]=useState(70);
  const withData=courses.flatMap(course=>{const metrics=course.terms[term];return metrics?[{...course,average:metrics.average,passRate:metrics.passRate,failureRate:failureRate(metrics),enrolled:metrics.enrolled,instructor:courseInstructor(course,term)}]:[]});
  const matching=withData.filter(row=>operator==='below'?row[metric]<value:row[metric]>value).sort((a,b)=>operator==='below'?a[metric]-b[metric]:b[metric]-a[metric]);
  const percentAll=courses.length?Math.round(matching.length/courses.length*1000)/10:0;
  const percentWithData=withData.length?Math.round(matching.length/withData.length*1000)/10:0;
  return <div className="space-y-6"><div className="card p-5"><div className="flex items-center gap-2"><SlidersHorizontal className="text-[#EA7600]" size={18}/><div><h2 className="font-extrabold">Threshold finder · {term}</h2><p className="text-xs text-slate-500">Find every course in the selected term that meets one metric rule.</p></div></div><div className="mt-5 grid gap-4 sm:grid-cols-3"><label><span className="label">Metric</span><select className="field" value={metric} onChange={event=>setMetric(event.target.value as 'average'|'failureRate')}><option value="average">Class average</option><option value="failureRate">Failure rate</option></select></label><label><span className="label">Condition</span><select className="field" value={operator} onChange={event=>setOperator(event.target.value as 'below'|'above')}><option value="below">Below</option><option value="above">Above</option></select></label><label><span className="label">Threshold (%)</span><input className="field" type="number" min="0" max="100" step="0.1" value={value} onChange={event=>setValue(Math.min(100,Math.max(0,Number(event.target.value))))}/></label></div></div>
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[['Courses meeting criteria',matching.length],['Percent of all courses',`${percentAll}%`],['Percent with term data',`${percentWithData}%`],['Courses with term data',`${withData.length} / ${courses.length}`]].map(([label,stat])=><div key={label} className="card p-5"><p className="text-[9px] font-black uppercase tracking-wider text-slate-500">{label}</p><p className="mt-1 text-3xl font-black text-[#003C71]">{stat}</p></div>)}</div>
    <div className="card overflow-x-auto"><div className="border-b border-slate-100 p-5"><h2 className="font-extrabold">{metric==='average'?'Class average':'Failure rate'} {operator} {value}%</h2><p className="text-xs text-slate-500">{matching.length} matching course{matching.length===1?'':'s'} in {term}</p></div><table className="w-full min-w-[760px]"><thead><tr className="table-head"><th className="p-4">Course</th><th>Instructor</th><th>Enrolled</th><th>Average</th><th>Pass rate</th><th className="pr-4">Failure rate</th></tr></thead><tbody className="divide-y divide-slate-100 text-xs">{matching.map(row=><tr key={row.id}><td className="p-4"><b>{row.code}</b><p className="text-slate-500">{row.title}</p></td><td>{row.instructor}</td><td>{row.enrolled}</td><td className="font-bold">{row.average}%</td><td>{row.passRate}%</td><td className="pr-4 font-bold text-red-700">{row.failureRate}%</td></tr>)}</tbody></table>{matching.length===0&&<p className="p-8 text-center text-xs text-slate-500">No courses meet this threshold.</p>}</div>
  </div>
}


function Submissions({courses,term,setTerm,overrides,onUpload,onOverride,importTargets}:{courses:any[];term:string;setTerm(v:string):void;overrides:Record<string,any>;onUpload(id:string):void;onOverride(id:string):void;importTargets(file:File):Promise<void>}){const[filter,setFilter]=useState<'all'|'submitted'|'outstanding'>('all');const[search,setSearch]=useState('');const[error,setError]=useState('');const rows=useMemo(()=>courses.map(c=>{const auto=Boolean(c.terms[term]);const override=overrides[`${c.id}_${term}`];return{...c,instructor:courseInstructor(c,term),auto,override,status:effectiveSubmission(auto,override)}}),[courses,term,overrides]);const visible=rows.filter(c=>(filter==='all'||c.status===filter)&&`${c.code} ${c.title} ${c.instructor}`.toLowerCase().includes(search.toLowerCase()));const submitted=rows.filter(c=>c.status==='submitted').length;return <div className="space-y-6"><div className="card flex flex-col justify-between gap-4 p-5 md:flex-row md:items-center"><div><h2 className="font-extrabold">Faculty grade submission checklist</h2><p className="text-xs text-slate-500">Uploads complete automatically; documented overrides take precedence.</p></div><div className="flex flex-wrap items-center gap-2"><TermSelect term={term} setTerm={setTerm}/><label className="btn-primary gap-2"><Upload size={14}/>Import target list<input type="file" accept=".csv" className="hidden" onChange={async e=>{if(e.target.files?.[0])try{setError('');await importTargets(e.target.files[0]);}catch(err){setError(err instanceof Error?err.message:'Import failed')}}}/></label><button className="btn-orange gap-2" onClick={()=>downloadCsv(`Outstanding_Grade_Submissions_${term}.csv`,rows.filter(c=>c.status==='outstanding').map(c=>({'Course Code':c.code,'Course Title':c.title,Instructor:c.instructor,Department:c.department,Term:term,Status:'Outstanding',Override:c.override?'Yes':'No'})))}><Download size={14}/>Export outstanding</button></div></div>{error&&<div className="rounded-lg bg-red-50 p-3 text-xs font-bold text-red-700">{error}</div>}<div className="grid grid-cols-3 gap-4">{[['Target courses',rows.length,'text-slate-900'],['Submitted',submitted,'text-emerald-600'],['Outstanding',rows.length-submitted,'text-red-600']].map(([l,v,c])=><div key={l} className="card p-5"><p className="text-[9px] font-black uppercase tracking-wider text-slate-500">{l}</p><p className={`mt-1 text-3xl font-black ${c}`}>{v}</p></div>)}</div><div className="card flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex rounded-lg bg-slate-100 p-1">{(['all','submitted','outstanding'] as const).map(x=><button key={x} className={`rounded-md px-3 py-1.5 text-xs font-bold capitalize ${filter===x?'bg-white shadow-sm':'text-slate-500'}`} onClick={()=>setFilter(x)}>{x}</button>)}</div><label className="relative"><Search size={15} className="absolute left-3 top-2.5 text-slate-400"/><input className="field py-2 pl-9" placeholder="Search courses…" value={search} onChange={e=>setSearch(e.target.value)}/></label></div><div className="card overflow-x-auto"><table className="w-full min-w-[840px]"><thead><tr className="table-head"><th className="p-4">Status</th><th>Course</th><th>Instructor</th><th>Term metrics</th><th className="pr-4 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-100 text-xs">{visible.map(c=><tr key={c.id} className={c.status==='submitted'?'bg-emerald-50/20':''}><td className="p-4"><Badge tone={c.status==='submitted'?'green':'red'}>{c.status}</Badge>{c.override&&<p className="mt-1 text-[9px] font-bold text-[#EA7600]">Manual override</p>}</td><td><b className="text-sm">{c.code}</b><p className="text-slate-500">{c.title}</p></td><td><b>{c.instructor}</b><p className="text-[10px] text-slate-400">{c.department}</p></td><td>{c.terms[term]?<><b>Avg {c.terms[term].average}%</b><p className="text-[10px] text-slate-500">{c.terms[term].enrolled} students · Pass {c.terms[term].passRate}%</p></>:<i className="text-slate-400">No grade upload</i>}</td><td className="pr-4 text-right"><button className="btn-ghost gap-1 text-[#003C71]" onClick={()=>onUpload(c.id)}><Upload size={13}/>{c.auto?'View / replace':'Upload grades'}</button><button className="btn-ghost" title="Manage status override" onClick={()=>onOverride(c.id)}><RefreshCw size={13}/></button></td></tr>)}</tbody></table></div></div>}

function StageEditor({stage,count,term,importantDates,onClose,onSave,onDelete}:{stage:Stage|null;count:number;term:string;importantDates:ImportantDate[];onClose():void;onSave(s:Omit<Stage,'documents'>):Promise<void>;onDelete?:()=>Promise<void>}){
  const termDates=useMemo(()=>importantDatesForTerm(importantDates,term),[importantDates,term]);
  const[form,setForm]=useState(()=>stage?{...stage}:{id:'',title:'',description:'',dueDate:new Date().toISOString().slice(0,10),isRequired:true,status:'pending' as StageStatus,sortOrder:count+1});
  const[importantDateId,setImportantDateId]=useState(()=>stage?termDates.find(date=>date.startsOn===stage.dueDate)?.id??'':'');
  const selectedImportantDate=termDates.find(date=>date.id===importantDateId);

  return <Modal title={stage?'Edit milestone':'Add milestone'} onClose={onClose}><form className="space-y-4 p-6" onSubmit={async e=>{e.preventDefault();await onSave(form)}}>
    <label><span className="label">Title</span><input className="field" required value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label>
    <label><span className="label">Description</span><textarea className="field" rows={3} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label>
    <label><span className="label">Important date · {term}</span><select className="field" value={importantDateId} onChange={e=>{const id=e.target.value;setImportantDateId(id);const date=termDates.find(item=>item.id===id);if(date)setForm({...form,dueDate:date.startsOn})}}>
      <option value="">Choose an important date (optional)</option>
      {termDates.map(date=><option key={date.id} value={date.id}>{formatDate(date.startsOn)} · {date.shortName}{date.endsOn!==date.startsOn?` (through ${formatDate(date.endsOn)})`:''}</option>)}
    </select></label>
    {termDates.length===0?<p className="rounded-lg bg-slate-50 p-3 text-xs text-slate-500">No important dates are stored for {term}. You can enter the due date manually.</p>:selectedImportantDate&&<p className="rounded-lg border border-blue-100 bg-blue-50 p-3 text-xs text-blue-900"><b>{selectedImportantDate.shortName}:</b> {selectedImportantDate.description}{selectedImportantDate.endsOn!==selectedImportantDate.startsOn&&<span className="mt-1 block font-semibold">The milestone uses the first day of this date range.</span>}</p>}
    <div className="grid grid-cols-2 gap-4"><label><span className="label">Due date</span><input className="field" type="date" required value={form.dueDate} onChange={e=>{setImportantDateId('');setForm({...form,dueDate:e.target.value})}}/></label><label><span className="label">Status</span><select className="field" value={form.status} onChange={e=>setForm({...form,status:e.target.value as StageStatus})}><option value="pending">Pending</option><option value="in-progress">In progress</option><option value="completed">Completed</option>{!form.isRequired&&<option value="skipped">Skipped</option>}</select></label></div>
    <label className="flex items-center justify-between rounded-lg border border-slate-200 p-3 text-xs font-bold">Mandatory milestone<input type="checkbox" checked={form.isRequired} onChange={e=>setForm({...form,isRequired:e.target.checked,status:e.target.checked&&form.status==='skipped'?'pending':form.status})}/></label>
    <div className="flex justify-between pt-2">{onDelete?<button type="button" className="btn-ghost text-red-600" onClick={()=>void onDelete()}><Trash2 size={14}/> Delete</button>:<span/>}<div className="flex gap-2"><button type="button" className="btn-ghost" onClick={onClose}>Cancel</button><button className="btn-orange">Save milestone</button></div></div>
  </form></Modal>;
}

function GradeUpload({courses,terms,canCreateTerms,onCreateTerm,onClose,onSubmit}:{courses:Course[];terms:string[];canCreateTerms:boolean;onCreateTerm(value:AcademicTermDraft):Promise<string>;onClose():void;onSubmit(courseCode:string,courseTitle:string|undefined,fileTerm:string,grades:number[]):Promise<void>}){
  const[result,setResult]=useState<GradeCsvResult>();
  const[matchedCourse,setMatchedCourse]=useState<Course>();
  const[destinationTerm,setDestinationTerm]=useState('');
  const[creatingTerm,setCreatingTerm]=useState(false);
  const[termNotice,setTermNotice]=useState('');
  const[busy,setBusy]=useState(false);
  const[submitError,setSubmitError]=useState('');
  const metrics=result?.grades.length?gradeMetrics(result.grades):null;
  const uploadedTerm=result?.semesterId??'';
  const needsTermChoice=Boolean(uploadedTerm&&!terms.includes(uploadedTerm));

  const handleFile=async(file:File)=>{
    const parsed=await parseGradeFile(file);
    const match=parsed.courseCode?findCourseByCode(parsed.courseCode,courses):undefined;
    setMatchedCourse(match);
    setDestinationTerm(parsed.semesterId&&terms.includes(parsed.semesterId)?parsed.semesterId:'');
    setTermNotice('');
    setSubmitError('');
    setResult(parsed);
  };

  return <><Modal title="Upload grades" onClose={onClose}><div className="space-y-4 p-6">
    <div className="rounded-lg border border-blue-200 bg-blue-50 p-3 text-xs text-blue-900"><b>Privacy guard:</b> Student ID and student names are validated only in this browser, then discarded. Only numeric grades are submitted.</div>
    <label className="flex cursor-pointer flex-col items-center rounded-xl border-2 border-dashed border-slate-300 p-7 text-center hover:border-[#003C71]"><Upload className="text-[#003C71]"/><b className="mt-2 text-sm">Choose grade CSV or Excel workbook</b><span className="mt-1 max-w-xl text-[10px] text-slate-500">The Course Code and Semester ID in the file suggest the destination · Uses the first Excel worksheet · 5 MB / 5,000 rows maximum</span><input type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" className="hidden" onChange={e=>e.target.files?.[0]&&void handleFile(e.target.files[0])}/></label>
    {result&&<>{result.errors.length>0?<div className="max-h-36 overflow-y-auto rounded-lg bg-red-50 p-3 text-xs text-red-700"><b>{result.errors.length} validation issue(s)</b><ul className="mt-1 list-disc pl-5">{result.errors.slice(0,20).map((x,i)=><li key={i}>{x}</li>)}</ul></div>:<div className={`rounded-lg p-3 text-xs ${matchedCourse?'bg-emerald-50 text-emerald-800':'border border-blue-200 bg-blue-50 text-blue-900'}`}><b>{matchedCourse?'Matched course:':'New course:'}</b> {matchedCourse?`${matchedCourse.code} — ${matchedCourse.title}`:`${result.courseCode}${result.courseTitle?` — ${result.courseTitle}`:''} will be added`}<br/><b>{destinationTerm?'Ready:':'Validated:'}</b> {result.grades.length} valid rows · average {metrics?.average}% · pass rate {metrics?.passRate}%{destinationTerm?` · destination term ${destinationTerm}`:' · choose a destination term below'}</div>}
      {needsTermChoice&&result.errors.length===0&&<div className="space-y-3 rounded-lg border border-amber-300 bg-amber-50 p-4 text-xs text-amber-950" role="group" aria-label="Resolve spreadsheet term"><div><b>Term {uploadedTerm} is not configured.</b><p className="mt-1">Choose an existing term for these grades, or create {uploadedTerm} as a new academic term.</p></div><label><span className="label text-amber-950">Existing destination term</span><select className="field bg-white" aria-label="Destination academic term" value={destinationTerm} onChange={event=>{setDestinationTerm(event.target.value);setTermNotice('')}}><option value="">Select an existing term</option>{terms.map(existingTerm=><option key={existingTerm} value={existingTerm}>{existingTerm}</option>)}</select></label>{canCreateTerms?<button type="button" className="btn-ghost border-amber-300 bg-white" onClick={()=>setCreatingTerm(true)}><Plus size={14}/>Create {uploadedTerm} term</button>:<p className="text-[10px]">You can map this upload to an existing term. A dean or academic director can create a new academic term.</p>}</div>}
      {destinationTerm&&uploadedTerm&&destinationTerm!==uploadedTerm&&<p className="rounded-lg border border-blue-200 bg-blue-50 p-3 text-xs text-blue-900"><b>Term reassignment:</b> Spreadsheet term {uploadedTerm} will be imported into {destinationTerm}.</p>}
      {termNotice&&<p className="rounded-lg bg-emerald-50 p-3 text-xs font-bold text-emerald-800" role="status">{termNotice}</p>}
      {result.warnings.length>0&&<div className="max-h-36 overflow-y-auto rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs text-amber-900"><b>File adjustments</b><ul className="mt-1 list-disc pl-5">{result.warnings.slice(0,20).map((warning,index)=><li key={index}>{warning}</li>)}</ul></div>}<div className="overflow-x-auto"><table className="w-full text-xs"><thead><tr className="table-head"><th className="p-2">Row</th><th>Student ID (discarded)</th><th>Student name (discarded)</th><th>Final Grade (%)</th></tr></thead><tbody>{result.preview.map(r=><tr key={r.row} className="border-b border-slate-100"><td className="p-2">{r.row}</td><td>{r.studentId}</td><td>{r.name}</td><td>{r.grade}</td></tr>)}</tbody></table></div></>}
    {submitError&&<p className="rounded-lg bg-red-50 p-3 text-xs font-bold text-red-700" role="alert">{submitError}</p>}
    <div className="flex justify-end gap-2"><button className="btn-ghost" onClick={onClose}>Cancel</button><button className="btn-orange" disabled={!result||result.errors.length>0||!result.courseCode||!destinationTerm||busy} onClick={async()=>{if(result?.courseCode&&destinationTerm){setBusy(true);setSubmitError('');try{await onSubmit(result.courseCode,result.courseTitle,destinationTerm,result.grades)}catch(reason){setSubmitError(reason instanceof Error?reason.message:'Grades could not be submitted.');setBusy(false)}}}}>{busy?'Submitting…':'Submit de-identified grades'}</button></div>
  </div></Modal>{creatingTerm&&<AcademicTermEditor initialCode={uploadedTerm} onClose={()=>setCreatingTerm(false)} onSave={async value=>{const code=await onCreateTerm(value);setDestinationTerm(code);setTermNotice(`Academic term ${code} was created and selected for this upload.`);setCreatingTerm(false)}}/>}</>;
}

function AcademicTermEditor({initialCode='',onClose,onSave}:{initialCode?:string;onClose():void;onSave(value:AcademicTermDraft):Promise<void>}){
  const[form,setForm]=useState<AcademicTermDraft>({code:initialCode,name:'',startsOn:'',endsOn:'',isCurrent:false});
  const[error,setError]=useState('');
  const[busy,setBusy]=useState(false);
  return <Modal title="Create academic term" onClose={onClose}><form className="space-y-4 p-6" onSubmit={async(event)=>{event.preventDefault();setBusy(true);setError('');try{await onSave({...form,code:form.code.toUpperCase()})}catch(reason){setError(reason instanceof Error?reason.message:'The academic term could not be created.');setBusy(false)}}}>
    <div className="rounded-lg border border-blue-200 bg-blue-50 p-3 text-xs text-blue-900">Term codes use <b>F</b>, <b>W</b>, or <b>S</b> followed by a two-digit year, such as F27.</div>
    <div className="grid gap-4 sm:grid-cols-2"><label><span className="label">Term code</span><input className="field uppercase" required pattern="[FfWwSs][0-9]{2}" maxLength={3} placeholder="F27" value={form.code} onChange={event=>setForm({...form,code:event.target.value.toUpperCase()})}/></label><label><span className="label">Term name</span><input className="field" required minLength={2} maxLength={100} placeholder="Fall 2027" value={form.name} onChange={event=>setForm({...form,name:event.target.value})}/></label><label><span className="label">Start date</span><input className="field" type="date" required value={form.startsOn} onChange={event=>setForm({...form,startsOn:event.target.value})}/></label><label><span className="label">End date</span><input className="field" type="date" required min={form.startsOn||undefined} value={form.endsOn} onChange={event=>setForm({...form,endsOn:event.target.value})}/></label></div>
    <label className="flex items-start gap-3 rounded-lg border border-slate-200 p-3"><input className="mt-0.5 h-4 w-4 accent-[#003C71]" type="checkbox" checked={form.isCurrent} onChange={event=>setForm({...form,isCurrent:event.target.checked})}/><span><b className="block text-xs">Make this the institution's current term</b><span className="mt-0.5 block text-[10px] text-slate-500">The new term is selected in this view either way.</span></span></label>
    {error&&<p className="rounded-lg bg-red-50 p-3 text-xs font-bold text-red-700" role="alert">{error}</p>}
    <div className="flex justify-end gap-2"><button type="button" className="btn-ghost" onClick={onClose}>Cancel</button><button className="btn-orange" disabled={busy}>{busy?'Creating…':'Create term'}</button></div>
  </form></Modal>;
}

function CourseEditorModal({course,term,profiles,onClose,onSave}:{course:Course;term:string;profiles:Profile[];onClose():void;onSave(value:CourseEditDraft):Promise<void>}){
  const details=course.termDetails?.[term];
  const inferredInstructor=profiles.find(profile=>profile.email.toLowerCase()===course.instructorEmail?.toLowerCase());
  const[form,setForm]=useState<CourseEditDraft>({code:course.code,title:course.title,department:course.department,section:details?.section??'',instructorId:details?.instructorId??inferredInstructor?.id});
  const[busy,setBusy]=useState(false);
  const[error,setError]=useState('');
  return <Modal title={`Edit ${course.code} · ${term}`} onClose={onClose}><form className="space-y-4 p-6" onSubmit={async event=>{event.preventDefault();setBusy(true);setError('');try{await onSave(form)}catch(reason){setError(reason instanceof Error?reason.message:'The course could not be updated.');setBusy(false)}}}>
    <div className="grid gap-4 sm:grid-cols-2"><label><span className="label">Course code</span><input className="field uppercase" required pattern="[A-Za-z]{4}[ -]?[0-9]{4}[ -]?[UuGg]?" value={form.code} onChange={event=>setForm({...form,code:event.target.value})}/></label><label><span className="label">Section · {term}</span><input className="field" maxLength={40} placeholder="e.g. 001" value={form.section} onChange={event=>setForm({...form,section:event.target.value})}/></label></div>
    <label><span className="label">Course title</span><input className="field" required minLength={2} maxLength={200} value={form.title} onChange={event=>setForm({...form,title:event.target.value})}/></label>
    <label><span className="label">Department</span><input className="field" required minLength={2} maxLength={120} value={form.department} onChange={event=>setForm({...form,department:event.target.value})}/></label>
    <label><span className="label">Instructor · {term}</span><select className="field" value={form.instructorId??''} onChange={event=>setForm({...form,instructorId:event.target.value||undefined})}><option value="">Unassigned</option>{profiles.filter(profile=>profile.isActive).map(profile=><option key={profile.id} value={profile.id}>{profile.fullName} · {profile.email}</option>)}</select></label>
    <p className="rounded-lg border border-blue-100 bg-blue-50 p-3 text-xs text-blue-900">Section and instructor apply only to {term}. Course code, title, and department apply across the course's full history.</p>
    {error&&<p className="rounded-lg bg-red-50 p-3 text-xs font-bold text-red-700" role="alert">{error}</p>}
    <div className="flex justify-end gap-2"><button type="button" className="btn-ghost" onClick={onClose}>Cancel</button><button className="btn-orange" disabled={busy}>{busy?'Saving…':'Save course'}</button></div>
  </form></Modal>;
}

function DeleteCourseModal({course,term,hasTerm,onClose,onDelete}:{course:Course;term:string;hasTerm:boolean;onClose():void;onDelete(scope:'term'|'history'):Promise<void>}){
  const[scope,setScope]=useState<'term'|'history'>(hasTerm?'term':'history');
  const[busy,setBusy]=useState(false);
  const[error,setError]=useState('');
  return <Modal title={`Remove ${course.code}`} danger onClose={onClose}><div className="space-y-4 p-6">
    <div className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-900"><b>Choose how much course data to remove.</b><p className="mt-2 text-xs leading-5">This action cannot be undone.</p></div>
    <div className="space-y-2" role="radiogroup" aria-label="Course removal scope"><label className={`flex cursor-pointer gap-3 rounded-lg border p-4 ${scope==='term'?'border-[#003C71] bg-blue-50':'border-slate-200'} ${!hasTerm?'cursor-not-allowed opacity-50':''}`}><input type="radio" name="course-removal-scope" value="term" checked={scope==='term'} disabled={!hasTerm} onChange={()=>setScope('term')}/><span><b className="block text-sm">Remove from {term} only</b><span className="mt-1 block text-xs text-slate-600">Deletes this term assignment, its grade uploads, analytics, submission targets, receipts, and override. Other terms remain.</span></span></label><label className={`flex cursor-pointer gap-3 rounded-lg border p-4 ${scope==='history'?'border-red-400 bg-red-50':'border-slate-200'}`}><input type="radio" name="course-removal-scope" value="history" checked={scope==='history'} onChange={()=>setScope('history')}/><span><b className="block text-sm">Delete entire course history</b><span className="mt-1 block text-xs text-slate-600">Permanently deletes {course.code}, every term assignment, all grade history, analytics, targets, receipts, and overrides.</span></span></label></div>
    {error&&<p className="rounded-lg bg-red-50 p-3 text-xs font-bold text-red-700" role="alert">{error}</p>}
    <div className="flex justify-end gap-2"><button type="button" className="btn-ghost" onClick={onClose}>Cancel</button><button type="button" className="btn-primary bg-red-700 hover:bg-red-800" disabled={busy} onClick={async()=>{setBusy(true);setError('');try{await onDelete(scope)}catch(reason){setError(reason instanceof Error?reason.message:'The course could not be removed.');setBusy(false)}}}>{busy?'Removing…':scope==='term'?`Remove from ${term}`:'Delete entire history'}</button></div>
  </div></Modal>;
}

function OverrideModal({course,current,onClose,onSave}:{course:any;current?:any;onClose():void;onSave(v?:'submitted'|'outstanding',reason?:string):Promise<void>}){const[value,setValue]=useState<'submitted'|'outstanding'>(current?.value??'submitted');const[reason,setReason]=useState(current?.reason??'');return <Modal title={`Submission override · ${course.code}`} onClose={onClose}><form className="space-y-4 p-6" onSubmit={async e=>{e.preventDefault();await onSave(value,reason)}}><label><span className="label">Effective status</span><select className="field" value={value} onChange={e=>setValue(e.target.value as any)}><option value="submitted">Submitted</option><option value="outstanding">Outstanding</option></select></label><label><span className="label">Required reason</span><textarea className="field" required minLength={5} rows={3} value={reason} onChange={e=>setReason(e.target.value)}/></label><div className="flex justify-between">{current?<button type="button" className="btn-ghost" onClick={()=>void onSave()}>Clear override</button>:<span/>}<div className="flex gap-2"><button type="button" className="btn-ghost" onClick={onClose}>Cancel</button><button className="btn-orange">Save override</button></div></div></form></Modal>}
